// Refactor 10 step 4.4: the page table of a workspace (plan B5). Each page of
// WorkspaceDetailPage has one entry, so the type check refuses a page with no
// entry. Generated by scripts/refactor-10/step-4/page-table.mjs from the ternary
// chain that ControlPortalApp.renderWorkspaceDetail built.
import type { BrainSection } from "@purin-labs/area-brain-contract/ui/features/brain/address";
import React from "react";
import { Navigate } from "react-router";
import {
  AccessRoute,
  AgentOperationsRoute,
  AgentsRoute,
  BankPayoutsRoute,
  BillingRoute,
  BrainRoute,
  CheckoutProfilesRoute,
  CommerceApiKeysRoute,
  CommerceEntityPlaneRoute,
  CostsPage,
  BakesRoute,
  DevicesRoute,
  HomePage,
  IntegrationsRoute,
  InventoryPage,
  JevFeaturesRoute,
  InventoryProductionRequestsPage,
  MailboxSettingsRoute,
  MailInboxRoute,
  MenuDraftRoute,
  OrderQueueRoute,
  PaymentsRoute,
  RecipesPage,
  RegisterRoute,
  SupplierPayoutsPanel,
  TerminalOperationsPanel,
  VaultRoute,
  WorkspaceSettingsRoute,
} from "./page-code";
import {
  workspacePagePath,
  workspaceAccessSubviewPath,
  workspaceResourcePath,
} from "@purin-labs/ui/route";
import { PageSkeleton } from "@purin-labs/ui/page-components";
import {
  checkoutProfileControlMutation,
  commerceBoardPresenceTransport,
  commerceEntityPlaneControlMutation,
  supplierPayoutControlMutation,
  terminalControlMutation,
} from "./portal-mutations";
import { canOperateCommerce, payoutReadRole } from "./portal-projection";
import { offerPriceAllowanceInteraction } from "./portal-reads";
import {
  brainLegacyPath,
  brainMemoryPath,
  commerceActionRefreshKey,
  commerceResourceHref,
  isCommercePage,
  mutationKindActive,
} from "./portal-routing";
import {
  ACCESS_ROUTE_TRANSPORT,
  AGENT_OPERATIONS_TRANSPORT,
  BRAIN_TRANSPORT,
  COMMERCE_OPERATIONS_TRANSPORT,
  INTEGRATIONS_ROUTE_TRANSPORT,
  PRODUCT_DESCRIPTION_ACTION_TRANSPORT,
  WORKSPACE_SETTINGS_ROUTE_TRANSPORT,
} from "./portal-transports";
import type { Variant } from "@purin-labs/type-utils";
import type { ControlPortalApp } from "./portal";
import type { PortalState } from "./portal-types";
import type { WorkspaceRouteSelection } from "./portal-routing";
import type { WorkspaceDetailPage } from "@purin-labs/ui/route";

/** What a page needs from the workspace shell. */
type PageContext = Readonly<{
  state: Variant<PortalState, "workspace_detail">;
  canManage: boolean;
  routeSelection: WorkspaceRouteSelection;
  app: Pick<
    ControlPortalApp,
    "loadCommerceAction" | "backCommercePage" | "setProposedCommerceAction"
  >;
}>;

interface PageEntry {
  readonly render: (page: PageContext) => React.ReactNode;
}

export const PAGES: Record<WorkspaceDetailPage, PageEntry> = {
  overview: { render: (page) => renderWorkspaceHome(page) },
  chat: { render: (page) => renderWorkspaceHome(page) },
  inbox: { render: (page) => renderInbox(page) },
  checkout: { render: (page) => renderCheckout(page) },
  products: {
    render: (page) =>
      page.routeSelection.resourceId === null
        ? renderInventory(page)
        : renderOrders(page),
  },
  menus: { render: (page) => renderMenus(page) },
  "order-queue": { render: (page) => renderOrderQueue(page) },
  register: { render: (page) => renderRegister(page) },
  terminals: { render: (page) => renderTerminals(page) },
  recipes: { render: (page) => renderRecipes(page) },
  costs: { render: (page) => renderCosts(page) },
  inventory: { render: (page) => renderInventory(page) },
  "production-requests": { render: (page) => renderProductionRequests(page) },
  orders: { render: (page) => renderOrders(page) },
  payments: { render: (page) => renderPayments(page) },
  payouts: { render: (page) => renderPayouts(page) },
  suppliers: { render: (page) => renderOrders(page) },
  "workflow-simulator": { render: (page) => renderWorkflowSimulator(page) },
  devices: { render: (page) => renderDevices(page) },
  bakes: { render: (page) => renderBakes(page) },
  agents: { render: (page) => renderAgents(page) },
  brain: { render: (page) => renderBrain(page) },
  knowledge: { render: (page) => renderKnowledge(page) },
  activity: { render: (page) => renderBrain(page) },
  tests: { render: (page) => renderBrain(page) },
  integrations: { render: (page) => renderWorkspaceHome(page) },
  vault: { render: (page) => renderVault(page) },
  "api-keys": { render: (page) => renderApiKeys(page) },
  jev: { render: (page) => renderJev(page) },
  billing: { render: (page) => renderBilling(page) },
  access: { render: (page) => renderWorkspaceHome(page) },
  settings: { render: (page) => renderWorkspaceHome(page) },
};

function brainRoute(page: PageContext, section: BrainSection): React.ReactNode {
  const { state, canManage, app } = page;
  return (
    <BrainRoute
      key={`${state.organisation.organisation.organisationId}:${section}`}
      section={section}
      skills={
        section === "knowledge" ? (
          <AgentOperationsRoute
            organisationId={state.organisation.organisation.organisationId}
            page="skills"
            canManage={canManage}
            commerceActionBusy={false}
            refreshKey={commerceActionRefreshKey(state.commerceAction)}
            loadAction={app.loadCommerceAction}
            transport={AGENT_OPERATIONS_TRANSPORT}
            commerceOperations={COMMERCE_OPERATIONS_TRANSPORT}
          />
        ) : null
      }
      organisationId={state.organisation.organisation.organisationId}
      canManage={canManage}
      transport={BRAIN_TRANSPORT}
      agentsHref={workspacePagePath(
        state.organisation.membership.organisationHandle,
        state.workspace.workspaceHandle,
        "agents",
      )}
      chatHref={workspacePagePath(
        state.organisation.membership.organisationHandle,
        state.workspace.workspaceHandle,
        "chat",
      )}
      contextLinks={{
        relatedCasesHref: workspaceAccessSubviewPath(
          state.organisation.membership.organisationHandle,
          state.workspace.workspaceHandle,
          "data_flow",
        ),
        // The Integrations page opens an integration that its address
        // names. TypeSafe is the connection of context discovery.
        discoveryHref: `${workspacePagePath(
          state.organisation.membership.organisationHandle,
          state.workspace.workspaceHandle,
          "integrations",
        )}?integration=typesafe`,
        // On screen sits beside Related Cases (Plan 87 phase 5).
        onScreenHref: `${workspaceAccessSubviewPath(
          state.organisation.membership.organisationHandle,
          state.workspace.workspaceHandle,
          "data_flow",
        )}#on-screen`,
      }}
    />
  );
}

function renderInbox(page: PageContext): React.ReactNode {
  const { state, canManage } = page;
  return (
    <MailInboxRoute
      key={state.organisation.organisation.organisationId}
      organisationId={state.organisation.organisation.organisationId}
      canManage={canManage}
      supplierHref={workspaceResourcePath.bind(
        null,
        state.organisation.membership.organisationHandle,
        state.workspace.workspaceHandle,
        "supplier",
      )}
      orderHref={workspaceResourcePath.bind(
        null,
        state.organisation.membership.organisationHandle,
        state.workspace.workspaceHandle,
        "customer_order",
      )}
      memoryHref={brainMemoryPath.bind(
        null,
        workspacePagePath(
          state.organisation.membership.organisationHandle,
          state.workspace.workspaceHandle,
          "knowledge",
        ),
      )}
      suppliersPath={workspacePagePath(
        state.organisation.membership.organisationHandle,
        state.workspace.workspaceHandle,
        "suppliers",
      )}
      integrationsPath={workspacePagePath(
        state.organisation.membership.organisationHandle,
        state.workspace.workspaceHandle,
        "integrations",
      )}
      mailboxSettings={(accountId, backHref) => (
        <React.Suspense
          fallback={<PageSkeleton label="Loading mailbox settings" />}
        >
          <MailboxSettingsRoute
            organisationId={state.organisation.organisation.organisationId}
            organisationHandle={
              state.organisation.membership.organisationHandle
            }
            workspaceHandle={state.workspace.workspaceHandle}
            refreshKey={String(state.configurationVersion)}
            canManage={canManage}
            canConnectCodex={state.organisation.membership.role === "owner"}
            transport={INTEGRATIONS_ROUTE_TRANSPORT}
            signedInAs={state.identity.displayName}
            accountId={accountId}
            back={{ href: backHref, label: "Inbox" }}
          />
        </React.Suspense>
      )}
    />
  );
}

function renderWorkflowSimulator(page: PageContext): React.ReactNode {
  return null;
}

function renderAgents(page: PageContext): React.ReactNode {
  const { state, canManage, app } = page;
  return (
    <AgentsRoute
      organisationId={state.organisation.organisation.organisationId}
      agentsHref={workspacePagePath(
        state.organisation.membership.organisationHandle,
        state.workspace.workspaceHandle,
        "agents",
      )}
      activityHref={`${workspacePagePath(
        state.organisation.membership.organisationHandle,
        state.workspace.workspaceHandle,
        "agents",
      )}?view=activity`}
      schedulesHref={`${workspacePagePath(
        state.organisation.membership.organisationHandle,
        state.workspace.workspaceHandle,
        "agents",
      )}?view=schedules`}
      activity={brainRoute(page, "agents")}
      runs={BRAIN_TRANSPORT}
      canManage={canManage}
      commerceActionBusy={mutationKindActive(
        state.mutations,
        "commerce_action",
      )}
      refreshKey={commerceActionRefreshKey(state.commerceAction)}
      loadAction={app.loadCommerceAction}
      transport={AGENT_OPERATIONS_TRANSPORT}
      commerceOperations={COMMERCE_OPERATIONS_TRANSPORT}
    />
  );
}

