function renderBrain(page: PageContext): React.ReactNode {
  const { state } = page;
  return (
    // Brain was one page, then Activity and Tests had their own. Their
    // old links open the page that holds the view now.
    <Navigate
      replace
      to={brainLegacyPath(
        workspacePagePath(
          state.organisation.membership.organisationHandle,
          state.workspace.workspaceHandle,
          "knowledge",
        ),
        window.location.search,
        state.page === "activity"
          ? "activity"
          : state.page === "tests"
            ? "evals"
            : "overview",
      )}
    />
  );
}

