function renderOrders(page: PageContext): React.ReactNode {
  const { state, canManage, routeSelection, app } = page;
  if (!isCommercePage(state.page)) return null;
  return (
    <>
      <CommerceEntityPlaneRoute
        organisationId={state.organisation.organisation.organisationId}
        page={state.page}
        resourceId={routeSelection.resourceId}
        resourceHref={commerceResourceHref.bind(
          null,
          state.organisation.membership.organisationHandle,
          state.workspace.workspaceHandle,
        )}
        onBack={app.backCommercePage.bind(
          app,
          state.page === "orders"
            ? "orders"
            : state.page === "suppliers"
              ? "suppliers"
              : "products",
        )}
        canManage={canManage}
        canOperate={canOperateCommerce(state.organisation.membership.role)}
        mutate={commerceEntityPlaneControlMutation}
        presence={commerceBoardPresenceTransport}
        commerceOperations={COMMERCE_OPERATIONS_TRANSPORT}
        descriptionDraftActions={PRODUCT_DESCRIPTION_ACTION_TRANSPORT}
        onActionProposed={app.setProposedCommerceAction.bind(app)}
        actionBusy={mutationKindActive(state.mutations, "commerce_action")}
        priceAllowances={offerPriceAllowanceInteraction(
          state.organisation.membership.role === "owner",
        )}
        payouts={
          state.page === "suppliers" && routeSelection.resourceId === null
            ? renderSupplierPayouts.bind(null, page)
            : undefined
        }
      />
    </>
  );
}

/**
 * Supplier payouts are the money side of the supplier relationship, so they
 * are a tab of Purchasing rather than a page of their own that nobody would
 * think to open.
 */
function renderSupplierPayouts(
  page: PageContext,
  report: (status: Readonly<{ readable: boolean; attention: number }>) => void,
): React.ReactNode {
  const { state } = page;
  return (
    <SupplierPayoutsPanel
      organisationId={state.organisation.organisation.organisationId}
      workspaceName={state.organisation.organisation.name}
      accessRole={payoutReadRole(state.organisation.membership.role)}
      access={ACCESS_ROUTE_TRANSPORT}
      mutate={supplierPayoutControlMutation}
      inTab
      onStatus={report}
    />
  );
}

function renderWorkspaceHome(page: PageContext): React.ReactNode {
  const { state, canManage, routeSelection, app } = page;
  const integrationsPage = state.page === "integrations";
  const accessPage = state.page === "access";
  const settingsPage = state.page === "settings";
  const homePage = state.page === "overview";
  const setupHomePage =
    homePage &&
    (state.organisation.organisation.lifecycle === "activating" ||
      state.organisation.organisation.lifecycle === "configuring");
  return (
    <>
      {setupHomePage || integrationsPage ? (
        <IntegrationsRoute
          organisationId={state.organisation.organisation.organisationId}
          organisationHandle={state.organisation.membership.organisationHandle}
          workspaceHandle={state.workspace.workspaceHandle}
          refreshKey={String(state.configurationVersion)}
          canManage={canManage}
          canConnectCodex={state.organisation.membership.role === "owner"}
          transport={INTEGRATIONS_ROUTE_TRANSPORT}
          signedInAs={state.identity.displayName}
        />
      ) : null}
      {homePage ? (
        <HomePage
          organisationId={state.organisation.organisation.organisationId}
          organisationHandle={state.organisation.membership.organisationHandle}
          workspaceHandle={state.workspace.workspaceHandle}
          operationsOnPage={!setupHomePage}
        />
      ) : null}
      {homePage && !setupHomePage ? (
        <AgentOperationsRoute
          organisationId={state.organisation.organisation.organisationId}
          page="operations"
          canManage={canManage}
          commerceActionBusy={mutationKindActive(
            state.mutations,
            "commerce_action",
          )}
          refreshKey={commerceActionRefreshKey(state.commerceAction)}
          loadAction={app.loadCommerceAction}
          transport={AGENT_OPERATIONS_TRANSPORT}
          commerceOperations={COMMERCE_OPERATIONS_TRANSPORT}
        />
      ) : null}
      {settingsPage ? (
        <WorkspaceSettingsRoute
          organisationId={state.organisation.organisation.organisationId}
          refreshKey={String(state.configurationVersion)}
          organisation={{
            name: state.organisation.organisation.name,
            lifecycle: state.organisation.organisation.lifecycle,
            role: state.organisation.membership.role,
          }}
          canManage={canManage}
          transport={WORKSPACE_SETTINGS_ROUTE_TRANSPORT}
          operationalAreas={
            canManage ? (
              <AgentOperationsRoute
                organisationId={state.organisation.organisation.organisationId}
                page="areas"
                canManage={canManage}
                commerceActionBusy={false}
                refreshKey={commerceActionRefreshKey(state.commerceAction)}
                loadAction={app.loadCommerceAction}
                transport={AGENT_OPERATIONS_TRANSPORT}
                commerceOperations={COMMERCE_OPERATIONS_TRANSPORT}
              />
            ) : null
          }
        />
      ) : null}
      {accessPage ? (
        <AccessRoute
          organisationId={state.organisation.organisation.organisationId}
          refreshKey={String(state.configurationVersion)}
          subview={routeSelection.accessSubview}
          paths={{
            access: workspaceAccessSubviewPath(
              state.organisation.membership.organisationHandle,
              state.workspace.workspaceHandle,
              "access",
            ),
            capabilities: workspaceAccessSubviewPath(
              state.organisation.membership.organisationHandle,
              state.workspace.workspaceHandle,
              "capabilities",
            ),
            data_flow: workspaceAccessSubviewPath(
              state.organisation.membership.organisationHandle,
              state.workspace.workspaceHandle,
              "data_flow",
            ),
          }}
          integrationsPath={workspacePagePath(
            state.organisation.membership.organisationHandle,
            state.workspace.workspaceHandle,
            "integrations",
          )}
          transport={ACCESS_ROUTE_TRANSPORT}
        />
      ) : null}
    </>
  );
}
